function longestTwoFaced(s: string): string {
  let bestStart = 0, bestLen = 0;
  for (let t = 1; t <= 26; t++) {
    const lo = new Array(26).fill(0), up = new Array(26).fill(0);
    let distinct = 0, both = 0, l = 0;
    const change = (ch: string, d: number) => {
      const code = ch.charCodeAt(0);
      const isLower = code >= 97, k = isLower ? code - 97 : code - 65;
      const wasAny = lo[k] + up[k] > 0, wasBoth = lo[k] > 0 && up[k] > 0;
      if (isLower) lo[k] += d;
      else up[k] += d;
      distinct += Number(lo[k] + up[k] > 0) - Number(wasAny);
      both += Number(lo[k] > 0 && up[k] > 0) - Number(wasBoth);
    };
    for (let r = 0; r < s.length; r++) {
      change(s[r], 1);
      while (distinct > t) change(s[l++], -1);
      const len = r - l + 1;
      if (distinct === t && both === t && (len > bestLen || (len === bestLen && l < bestStart))) {
        bestStart = l;
        bestLen = len;
      }
    }
  }
  return s.slice(bestStart, bestStart + bestLen);
}

