class Solution:
    def longestTwoFaced(self, s: str) -> str:
        best_start = best_len = 0
        for t in range(1, 27):
            lo, up = [0] * 26, [0] * 26
            state = {"distinct": 0, "both": 0}

            def change(ch, d):
                k = ord(ch.lower()) - 97
                was_any, was_both = lo[k] + up[k] > 0, lo[k] > 0 and up[k] > 0
                if ch.islower():
                    lo[k] += d
                else:
                    up[k] += d
                state["distinct"] += (lo[k] + up[k] > 0) - was_any
                state["both"] += (lo[k] > 0 and up[k] > 0) - was_both

            l = 0
            for r, ch in enumerate(s):
                change(ch, 1)
                while state["distinct"] > t:
                    change(s[l], -1)
                    l += 1
                size = r - l + 1
                if state["distinct"] == t and state["both"] == t and (
                    size > best_len or (size == best_len and l < best_start)
                ):
                    best_start, best_len = l, size
        return s[best_start:best_start + best_len]

